1	import { db } from "./db";
2	import { MODEL_RATES } from "./models";
3	
4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// This is Kodely's clearest wedge against the category (see the board's
9	// "credit bill-shock" differentiation cards), so it lives in one small module.
10	
11	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
12	export const MICROS_PER_CREDIT = 2_000;
13	
14	/**
15	 * New accounts start with enough to build and iterate on a real page.
16	 * Sized from measured real costs (2026-08-17): a full first build runs
17	 * ~$0.29 (144 credits), a follow-up edit ~$0.34 (172 credits) on Sonnet 5 —
18	 * 750 covers roughly one build plus 2-3 real edits.
19	 */
20	export const SIGNUP_GRANT = 750;
21	
22	export type Usage = {
23	  inputTokens: number;
24	  outputTokens: number;
25	  cacheReadTokens: number;
26	  cacheWriteTokens: number;
27	};
28	
29	/**
30	 * Micro-dollars of real model spend for a given usage on a given model.
31	 * MODEL_RATES stores USD per MILLION tokens, which — numerically — is
32	 * already USD-per-token expressed in micro-dollars (1e-6 USD = 1 microUSD).
33	 * So `rate * tokens` IS the cost in micros directly; do NOT also divide by
34	 * 1e6, that computes cost in whole dollars instead and silently floors every
35	 * build under $0.50 to 0 (which is exactly the bug this comment replaced —
36	 * caught 2026-08-17 when a real ~$0.22 build was charged only 1 credit).
37	 */
38	export function costMicros(model: string, usage: Usage): number {
39	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
40	  const perToken = (perMTok: number, tokens: number) => perMTok * tokens;
41	  return Math.round(
42	    perToken(rate.input, usage.inputTokens) +
43	      perToken(rate.output, usage.outputTokens) +
44	      perToken(rate.cacheRead, usage.cacheReadTokens) +
45	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
46	  );
47	}
48	
49	export function creditsFor(micros: number): number {
50	  // Zero measured cost means zero credits. The floor below exists so a real
51	  // but tiny cost never rounds down to free — it must NOT turn a build with no
52	  // metered spend at all into a 1-credit charge.
53	  //
54	  // This is not hypothetical: on the SDK engine a build whose telemetry is
55	  // missing reports 0 tokens and 0 micros (see meterUsage in lib/agent-sdk.ts),
56	  // and every one of those was being billed a credit for spend that provably
57	  // did not happen — inside the one module whose stated purpose is never doing
58	  // that. Found 2026-08-22 in a real ledger row.
59	  if (micros <= 0) return 0;
60	  return Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
61	}
62	
63	export async function getBalance(userId: string): Promise<number> {
64	  const latest = await db.creditLedger.findFirst({
65	    where: { userId },
66	    orderBy: { createdAt: "desc" },
67	  });
68	  return latest?.balanceAfter ?? 0;
69	}
70	
71	export async function grantCredits(userId: string, amount: number, reason: string) {
72	  const balance = await getBalance(userId);
73	  return db.creditLedger.create({
74	    data: { userId, delta: amount, reason, balanceAfter: balance + amount },
75	  });
76	}
77	
78	/**
79	 * Charge for a SUCCESSFUL build. Never call this on a failed build — the whole
80	 * promise to the customer is that broken output is free.
81	 */
82	export async function chargeForBuild(userId: string, buildId: string, credits: number) {
83	  const balance = await getBalance(userId);
84	  await db.creditLedger.create({
85	    data: {
86	      userId,
87	      delta: -credits,
88	      reason: "build",
89	      buildId,
90	      balanceAfter: balance - credits,
91	    },
92	  });
93	  return balance - credits;
94	}
95	
96	/**
97	 * Pre-flight estimate shown BEFORE the user spends anything. Deliberately a
98	 * range derived from observed build sizes, not a fake precise number.
99	 *
100	 * Numbers corrected 2026-08-21. The previous 8-30 / 3-15 ranges predated the
101	 * costMicros fix and understated real spend by roughly an order of magnitude —
102	 * on a product whose headline promise is no bill shock, an estimate that low
103	 * is worse than showing nothing.
104	 *
105	 * The honest state of our evidence: measured builds have come in at ~144
106	 * credits (2026-08-17) and ~472 credits (2026-08-21, a first build of a
107	 * tradesman site via the eval harness). That is a 3x spread across two
108	 * samples, so the range below is deliberately wide rather than falsely
109	 * precise, and skews high — quoting low and charging high is the exact
110	 * failure this whole module exists to prevent.
111	 *
112	 * REPLACE THIS with real percentiles once the eval harness has run a full
113	 * sweep (scripts/eval). Two data points is not a distribution.
114	 */
115	export function estimateCredits(kind: "create" | "edit"): { low: number; high: number } {
116	  return kind === "create" ? { low: 120, high: 550 } : { low: 60, high: 300 };
117	}
118	
119	/**
120	 * Fallback when a user has no build history to average. Sits near the upper
121	 * of our two measurements on purpose: this drives "about N more builds", and
122	 * over-promising remaining builds is how someone hits zero mid-build.
123	 */
124	const TYPICAL_BUILD_CREDITS = 400;
125	
126	/**
127	 * What a build actually costs THIS user, averaged over their recent successful
128	 * builds. Personal history beats a global constant: someone building one-page
129	 * sites and someone building ten-page sites deserve different answers to
130	 * "how many builds do I have left?".
131	 */
132	export async function averageBuildCredits(userId: string): Promise<number> {
133	  const recent = await db.build.findMany({
134	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
135	    orderBy: { createdAt: "desc" },
136	    take: 10,
137	    select: { creditsCharged: true },
138	  });
139	  if (recent.length === 0) return TYPICAL_BUILD_CREDITS;
140	  const total = recent.reduce((sum, b) => sum + b.creditsCharged, 0);
141	  return Math.max(1, Math.round(total / recent.length));
142	}
143	
144	// ── Self-imposed spend cap ────────────────────────────────────────────────
145	// Point 4 of the anti-bill-shock contract. The three rules above stop us from
146	// OVERCHARGING for a given build; none of them stop a user from running fifty
147	// builds in an afternoon and being genuinely shocked by the total. A ceiling
148	// the user sets themselves is the honest answer, and it is the one guard a
149	// competitor's $607-against-a-$25-plan incident would have needed.
150	//
151	// Rolling 30 days, not calendar month, so there is no "reset day" to game and
152	// no cliff where a cap silently stops protecting someone mid-month.
153	
154	const CAP_WINDOW_DAYS = 30;
155	
156	export type SpendCapStatus = {
157	  /** NULL when the user has set no cap. */
158	  cap: number | null;
159	  spent: number;
160	  /** Credits still available under the cap; Infinity when uncapped. */
161	  remaining: number;
162	  reached: boolean;
163	};
164	
165	/** Credits spent on builds in the rolling window. Grants are excluded. */
166	export async function spentInWindow(userId: string): Promise<number> {
167	  const since = new Date(Date.now() - CAP_WINDOW_DAYS * 24 * 60 * 60 * 1000);
168	  const { _sum } = await db.creditLedger.aggregate({
169	    where: { userId, createdAt: { gte: since }, delta: { lt: 0 } },
170	    _sum: { delta: true },
171	  });
172	  // Deltas are negative for spend; report it as a positive number.
173	  return Math.abs(_sum.delta ?? 0);
174	}
175	
176	export async function getSpendCapStatus(userId: string): Promise<SpendCapStatus> {
177	  const user = await db.user.findUnique({
178	    where: { id: userId },
179	    select: { spendCapCredits: true },
180	  });
181	  const cap = user?.spendCapCredits ?? null;
182	
183	  if (cap === null) {
184	    return { cap: null, spent: 0, remaining: Infinity, reached: false };
185	  }
186	
187	  const spent = await spentInWindow(userId);
188	  return { cap, spent, remaining: Math.max(0, cap - spent), reached: spent >= cap };
189	}
