1	import { db } from "@/lib/db";
2	import { getCurrentUser } from "@/lib/auth";
3	import { runAgent, normalizePath, type FileMap } from "@/lib/agent";
4	import { buildSite, BuildError } from "@/lib/build-site";
5	import { chargeForBuild, costMicros, creditsFor, getBalance, getSpendCapStatus } from "@/lib/credits";
6	import { checkGenerateRateLimit } from "@/lib/rate-limit";
7	import { track, EVENTS } from "@/lib/events";
8	import { classifyFollowUp } from "@/lib/feedback-intent";
9	
10	export const dynamic = "force-dynamic";
11	export const maxDuration = 300;
12	
13	function sse(event: unknown) {
14	  return `data: ${JSON.stringify(event)}\n\n`;
15	}
16	
17	// A build that fails to compile even after one repair attempt gives up — this
18	// bounds the worst case to ~2x the cost of a normal generation, not unbounded.
19	const MAX_BUILD_ATTEMPTS = 2;
20	
21	export async function POST(req: Request) {
22	  const user = await getCurrentUser();
23	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
24	
25	  const body = (await req.json().catch(() => null)) as {
26	    projectId?: string;
27	    prompt?: string;
28	    image?: string;
29	  } | null;
30	  const prompt = body?.prompt?.trim();
31	  if (!body?.projectId || !prompt) {
32	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
33	  }
34	
35	  // Only a data: URL (what the client-side downscale in PromptHero produces)
36	  // is accepted — anything else is silently dropped rather than passed on.
37	  const imageMatch = body.image?.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
38	  const image = imageMatch ? { mediaType: imageMatch[1], data: imageMatch[2] } : undefined;
39	
40	  const project = await db.project.findFirst({
41	    where: { id: body.projectId, userId: user.id },
42	    include: { messages: { orderBy: { createdAt: "asc" } } },
43	  });
44	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
45	
46	  const balance = await getBalance(user.id);
47	  if (balance <= 0) {
48	    track(EVENTS.creditsExhausted, { userId: user.id, props: { projectId: project.id } });
49	    return Response.json(
50	      { error: "You're out of credits. Top up to keep building." },
51	      { status: 402 },
52	    );
53	  }
54	
55	  // The user's own ceiling, checked before anything is spent. Distinct from
56	  // running out of credits: they still HAVE the balance, they asked us not to
57	  // burn past this without them saying so. The message says exactly that, so
58	  // it never reads as a surprise limit we imposed.
59	  const cap = await getSpendCapStatus(user.id);
60	  if (cap.reached) {
61	    track(EVENTS.spendCapReached, {
62	      userId: user.id,
63	      props: { cap: cap.cap, spent: cap.spent, projectId: project.id },
64	    });
65	    return Response.json(
66	      {
67	        error: `You've hit your own spending cap of ${cap.cap} credits per 30 days (${cap.spent} used). Raise or remove it in Settings to keep building.`,
68	        spendCapReached: true,
69	      },
70	      { status: 402 },
71	    );
72	  }
73	
74	  const rateLimit = await checkGenerateRateLimit(user.id);
75	  if (!rateLimit.allowed) {
76	    return Response.json(
77	      { error: "You're generating too fast — take a short break and try again shortly." },
78	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
79	    );
80	  }
81	
82	  // The foundation means source files are never empty — "first build" is
83	  // instead "first real customization request" for this project.
84	  const kind = project.messages.length === 0 ? "create" : "edit";
85	
86	  const build = await db.build.create({
87	    data: { projectId: project.id, status: "RUNNING", model: "", prompt },
88	  });
89	
90	  track(EVENTS.buildStarted, {
91	    userId: user.id,
92	    props: {
93	      buildId: build.id,
94	      projectId: project.id,
95	      kind,
96	      hasImage: Boolean(image),
97	      // Only meaningful on an edit — a first build has no prior output to be
98	      // reacting to. Left off `create` so followUpIntents() isn't diluted by
99	      // rows that were never follow-ups.
100	      ...(kind === "edit" ? { intent: classifyFollowUp(prompt) } : {}),
101	    },
102	  });
103	
104	  await db.message.create({
105	    data: { projectId: project.id, role: "user", content: prompt },
106	  });
107	
108	  // Aborted when the client disconnects (tab closed, network drop) — cancels
109	  // the in-flight Anthropic request instead of burning tokens for nobody.
110	  const abortController = new AbortController();
111	
112	  const encoder = new TextEncoder();
113	  const stream = new ReadableStream({
114	    async start(controller) {
115	      // A client disconnect races with our own sends: enqueue on a closed
116	      // controller throws "Controller is already closed", which used to be
117	      // caught as a generic failure and wrongly mark an otherwise-fine build
118	      // FAILED. There's nothing to do about a gone client — swallow it.
119	      const send = (event: unknown) => {
120	        try {
121	          controller.enqueue(encoder.encode(sse(event)));
122	        } catch {
123	          // client is gone
124	        }
125	      };
126	
127	      let filesWritten = 0;
128	      let succeeded = false;
129	      // 0 means it compiled first try. This is the raw material for the
130	      // green-build-first-try metric (see greenBuildRate in lib/events.ts),
131	      // which the roadmap treats as a gate but nothing measured before.
132	      // Declared out here so the catch below can record it too.
133	      let repairAttempts = 0;
134	      const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
135	      let model = "";
136	      let lastReply = "";
137	      let lastProgress = "";
138	
139	      const readSourceFiles = async (): Promise<FileMap> => {
140	        const rows = await db.projectFile.findMany({
141	          where: { projectId: project.id, published: false, kind: "source" },
142	        });
143	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
144	      };
145	
146	      try {
147	        let request = prompt;
148	        let buildOutput: FileMap | null = null;
149	        let lastBuildError = "";
150	
151	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
152	          if (abortController.signal.aborted) break;
153	
154	          const generator = runAgent({
155	            history: project.messages.map((m) => ({
156	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
157	              content: m.content,
158	            })),
159	            request,
160	            files: await readSourceFiles(),
161	            kind,
162	            // Only attached on the very first turn of a project — a repair
163	            // retry re-sends the same `request` text but should not attach
164	            // the image again mid-loop.
165	            image: attempt === 1 ? image : undefined,
166	            signal: abortController.signal,
167	            onWrite: async (path, content) => {
168	              if (!normalizePath(path)) return false;
169	              await db.projectFile.upsert({
170	                where: {
171	                  projectId_path_published_kind: {
172	                    projectId: project.id,
173	                    path,
174	                    published: false,
175	                    kind: "source",
176	                  },
177	                },
178	                create: { projectId: project.id, path, content, published: false, kind: "source" },
179	                update: { content },
180	              });
181	              filesWritten++;
182	              return true;
183	            },
184	            onDelete: async (path) => {
185	              const { count } = await db.projectFile.deleteMany({
186	                where: { projectId: project.id, path, published: false, kind: "source" },
187	              });
188	              return count > 0;
189	            },
190	          });
191	
192	          for await (const event of generator) {
193	            if (event.type === "text") {
194	              lastReply += event.text;
195	              send(event);
196	            } else if (event.type === "file") {
197	              send(event);
198	            } else if (event.type === "status") {
199	              send(event);
200	            } else if (event.type === "progress") {
201	              // Collapse consecutive identical lines. A run of twelve Reads
202	              // narrates as one "Looking through the project" rather than
203	              // twelve, which would read as a stutter rather than progress.
204	              if (event.text !== lastProgress) {
205	                lastProgress = event.text;
206	                send(event);
207	              }
208	            } else if (event.type === "usage") {
209	              model = event.model;
210	              totals.inputTokens += event.inputTokens;
211	              totals.outputTokens += event.outputTokens;
212	              totals.cacheReadTokens += event.cacheReadTokens;
213	              totals.cacheWriteTokens += event.cacheWriteTokens;
214	            }
215	          }
216	
217	          if (abortController.signal.aborted) break;
218	
219	          try {
220	            send({ type: "progress", text: "Compiling the site" });
221	            buildOutput = await buildSite(await readSourceFiles());
222	            break; // compiled cleanly — done
223	          } catch (err) {
224	            lastBuildError = err instanceof BuildError ? err.message : String(err);
225	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
226	            repairAttempts++;
227	            // Clear the dedupe key: the repair pass legitimately repeats the
228	            // same lines, and suppressing them would look like a stall.
229	            lastProgress = "";
230	            send({ type: "status", text: "Build didn't compile — fixing it…" });
231	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
232	          }
233	        }
234	
235	        if (abortController.signal.aborted || !buildOutput) {
236	          // Loop ended without a successful build and without throwing —
237	          // only reachable via the abort path (see the `break` above).
238	        } else {
239	          succeeded = true;
240	
241	          // Replace the compiled tree with the new build output.
242	          await db.$transaction([
243	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
244	            ...(Object.keys(buildOutput).length > 0
245	              ? [
246	                  db.projectFile.createMany({
247	                    data: Object.entries(buildOutput).map(([path, content]) => ({
248	                      projectId: project.id,
249	                      path,
250	                      content,
251	                      published: false,
252	                      kind: "build",
253	                    })),
254	                  }),
255	                ]
256	              : []),
257	          ]);
258	
259	          const micros = costMicros(model, totals);
260	          const credits = creditsFor(micros);
261	          // A zero charge writes no ledger row. The ledger is a financial
262	          // record; an entry that moves nothing is noise in a statement a
263	          // customer may one day be reading to understand their bill.
264	          const remaining =
265	            credits > 0
266	              ? await chargeForBuild(user.id, build.id, credits)
267	              : await getBalance(user.id);
268	
269	          const sourceFiles = await readSourceFiles();
270	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
271	
272	          await db.build.update({
273	            where: { id: build.id },
274	            data: {
275	              status: "SUCCEEDED",
276	              model,
277	              endedAt: new Date(),
278	              inputTokens: totals.inputTokens,
279	              outputTokens: totals.outputTokens,
280	              cacheReadTokens: totals.cacheReadTokens,
281	              cacheWriteTokens: totals.cacheWriteTokens,
282	              filesWritten,
283	              repairAttempts,
284	              costMicros: micros,
285	              creditsCharged: credits,
286	              filesSnapshot,
287	            },
288	          });
289	
290	          track(EVENTS.buildSucceeded, {
291	            userId: user.id,
292	            props: {
293	              buildId: build.id,
294	              projectId: project.id,
295	              kind,
296	              model,
297	              repairAttempts,
298	              filesWritten,
299	              credits,
300	              remaining,
301	            },
302	          });
303	
304	          if (lastReply.trim()) {
305	            await db.message.create({
306	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
307	            });
308	          }
309	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
310	
311	          // buildId travels to the client so it can attach a rating to this
312	          // specific build (see app/api/feedback/route.ts).
313	          send({ type: "done", credits, remaining, filesWritten, buildId: build.id });
314	        }
315	
316	        if (!succeeded) {
317	          await db.build.update({
318	            where: { id: build.id },
319	            data: {
320	              status: "FAILED",
321	              endedAt: new Date(),
322	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
323	              filesWritten,
324	              repairAttempts,
325	              creditsCharged: 0,
326	              // Record the model on failure too, when we got far enough to
327	              // learn it. It used to be written only on success, so every
328	              // failed build had a blank Model column — which made it
329	              // impossible to attribute a spike in failures to a model change,
330	              // exactly when you most need to.
331	              ...(model ? { model } : {}),
332	            },
333	          });
334	
335	          track(EVENTS.buildFailed, {
336	            userId: user.id,
337	            props: {
338	              buildId: build.id,
339	              projectId: project.id,
340	              kind,
341	              repairAttempts,
342	              reason: abortController.signal.aborted ? "aborted" : "no_output",
343	            },
344	          });
345	        }
346	      } catch (error) {
347	        // A build that fails is never charged — that is the product promise,
348	        // so the ledger is deliberately untouched on this path.
349	        const message =
350	          error instanceof Error ? error.message : "The build failed unexpectedly.";
351	        console.error("[kodely] build failed", build.id, error);
352	
353	        await db.build.update({
354	          where: { id: build.id },
355	          data: {
356	            status: "FAILED",
357	            endedAt: new Date(),
358	            error: message.slice(0, 1000),
359	            filesWritten,
360	            repairAttempts,
361	            creditsCharged: 0,
362	            // See the note on the other failure path — a blank model makes a
363	            // failure impossible to attribute.
364	            ...(model ? { model } : {}),
365	          },
366	        });
367	
368	        track(EVENTS.buildFailed, {
369	          userId: user.id,
370	          props: {
371	            buildId: build.id,
372	            projectId: project.id,
373	            kind,
374	            repairAttempts,
375	            reason: "error",
376	          },
377	        });
378	
379	        send({ type: "error", message });
380	      } finally {
381	        try {
382	          controller.close();
383	        } catch {
384	          // already closed by the client disconnect path
385	        }
386	      }
387	    },
388	    cancel() {
389	      // The client disconnected — stop the in-flight Anthropic request
390	      // rather than let it run to completion for a response nobody reads.
391	      abortController.abort();
392	    },
393	  });
394	
395	  return new Response(stream, {
396	    headers: {
397	      "Content-Type": "text/event-stream; charset=utf-8",
398	      "Cache-Control": "no-cache, no-transform",
399	      Connection: "keep-alive",
400	    },
401	  });
402	}
