import nodemailer from "nodemailer";
import { db } from "@/lib/db";
import { isMailConfigured } from "@/lib/mail";
import { getBalance, averageBuildCredits } from "@/lib/credits";
import { billingEnabled } from "@/lib/stripe";
import { creditState } from "./credit-state";
import {
  appUrl,
  buildFailedEmail,
  lowCreditsEmail,
  sitePublishedEmail,
  welcomeEmail,
  type Email,
  type EmailKind,
} from "./templates";

// The notification dispatcher.
//
// Two hard rules, both enforced structurally rather than by convention:
//
//   1. EVERY SEND IS ADDRESSED FROM THE DATABASE. No function here takes an
//      email address. You pass a userId / buildId / projectId, and the
//      recipient is looked up from that row's owner. It is therefore not
//      possible to call anything in this file in a way that mails one person
//      another person's account state.
//   2. NOTHING HERE CAN FAIL A REQUEST. Every send* function catches its own
//      errors and returns a result; the notify* wrappers don't even return a
//      promise. A dead SMTP server must never fail a build, a publish or a
//      signup.

// ── Transport ─────────────────────────────────────────────────────────────
//
// NOTE FOR THE OWNER OF lib/mail.ts — this is the one piece of duplication in
// this module and it should not survive. lib/mail.ts already builds and caches
// exactly this transporter, but keeps it module-private and exposes only
// sendContactEmail(), which always sends to CONTACT_TO. There is no exported
// way to send an arbitrary transactional message, and this module may not edit
// that file. So the transport below is deliberately built from THE SAME env
// vars, with the same secure/port logic and the same envelope sender, and the
// "is it configured" predicate is imported rather than re-implemented.
//
// The patch that deletes this block is ~6 lines in lib/mail.ts:
//
//   export async function sendMail(msg: nodemailer.SendMailOptions) {
//     await transporter().sendMail({ from: FROM, ...msg });
//   }
//
// Once that exists, import it here and delete `transport()` and `FROM`.

const FROM = process.env.MAIL_FROM ?? "Kodely <noreply@kodely.me>";
const PORT = Number(process.env.SMTP_PORT ?? 587);

let cached: nodemailer.Transporter | null = null;

function transport(): nodemailer.Transporter {
  if (!cached) {
    cached = nodemailer.createTransport({
      host: process.env.SMTP_HOST,
      port: PORT,
      secure: PORT === 465,
      auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
      // The cron path sends in a loop; a hung SMTP connection must not wedge
      // the whole run. lib/mail.ts doesn't set these because its one caller is
      // a single interactive request.
      connectionTimeout: 10_000,
      greetingTimeout: 10_000,
      socketTimeout: 20_000,
    });
  }
  return cached;
}

// ── Operational guards ────────────────────────────────────────────────────

/** Master off switch. Set KODELY_NOTIFY_DISABLED=1 to stop all sending. */
function disabled(): boolean {
  return process.env.KODELY_NOTIFY_DISABLED === "1";
}

/** Compose and log, never hand anything to SMTP. */
function dryRun(): boolean {
  return process.env.KODELY_NOTIFY_DRY_RUN === "1";
}

/**
 * Rollout safety net. With KODELY_NOTIFY_ALLOWLIST set to a comma-separated
 * list of addresses, everyone else is skipped. Turn this on first, watch real
 * mail arrive at your own address, then remove it.
 */
function allowlist(): Set<string> | null {
  const raw = process.env.KODELY_NOTIFY_ALLOWLIST;
  if (!raw) return null;
  const entries = raw
    .split(",")
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean);
  return entries.length > 0 ? new Set(entries) : null;
}

// ── Duplicate suppression, process-local ──────────────────────────────────
//
// This is the SECOND line of defence only. The real idempotency lives in
// lib/notifications/scan.ts, which derives each notification from a state
// transition that can only fall inside one cron slot. This map exists to make
// a retried or overlapping cron run (or a double-wired inline hook) a no-op
// within one process lifetime. It resets on deploy — same trade-off, and the
// same honest limitation, as the throttle in app/api/contact/route.ts.

const RECENT_TTL_MS = 6 * 60 * 60 * 1000;
const RECENT_MAX = 20_000;

const globalForNotify = globalThis as unknown as { kodelyNotifySent?: Map<string, number> };
const recent: Map<string, number> = (globalForNotify.kodelyNotifySent ??= new Map());

/**
 * True the first time a given (kind, dedupeKey) is seen, false afterwards.
 * The key must identify the *occurrence*, not the person: a ledger row id, a
 * build id, a project id — never just a userId for anything repeatable.
 */
function claim(kind: EmailKind, dedupeKey: string): boolean {
  const now = Date.now();
  if (recent.size > RECENT_MAX) {
    for (const [k, t] of recent) if (now - t > RECENT_TTL_MS) recent.delete(k);
    if (recent.size > RECENT_MAX) recent.clear();
  }
  const key = `${kind}:${dedupeKey}`;
  const seen = recent.get(key);
  if (seen !== undefined && now - seen < RECENT_TTL_MS) return false;
  recent.set(key, now);
  return true;
}

/** Undo a claim when the send didn't actually happen, so a retry can try again. */
function release(kind: EmailKind, dedupeKey: string): void {
  recent.delete(`${kind}:${dedupeKey}`);
}

// ── Delivery ──────────────────────────────────────────────────────────────

export type SendResult = {
  sent: boolean;
  kind: EmailKind;
  /** Machine-readable outcome: "sent", "not_configured", "duplicate", ... */
  reason: string;
};

async function deliver(to: string, email: Email): Promise<void> {
  if (dryRun()) {
    console.log(`[notifications] DRY RUN — would send "${email.subject}" to ${to}`);
    return;
  }
  await transport().sendMail({
    from: FROM,
    // The bare address, never `Name <addr>`: a display name is user-supplied
    // and a CR/LF in it would be header injection (see headerSafe in
    // lib/mail.ts). Nothing user-controlled reaches a header from here.
    to,
    subject: email.subject,
    text: email.text,
    html: email.html,
  });
}

/**
 * Shared shell for every notification: guards, recipient resolution, dedupe,
 * delivery, and the promise that nothing throws.
 *
 * `build` returns null to abstain — used by every caller to re-check its own
 * precondition against the database immediately before sending, so a stale
 * scan result can never turn into a wrong email.
 */
async function send(
  kind: EmailKind,
  dedupeKey: string,
  build: () => Promise<{ to: string; email: Email } | null>,
): Promise<SendResult> {
  const done = (sent: boolean, reason: string): SendResult => ({ sent, kind, reason });

  try {
    if (disabled()) return done(false, "disabled");
    if (!isMailConfigured() && !dryRun()) return done(false, "not_configured");
    if (!claim(kind, dedupeKey)) return done(false, "duplicate");

    let target: { to: string; email: Email } | null = null;
    try {
      target = await build();
    } catch (err) {
      release(kind, dedupeKey);
      console.error(`[notifications] ${kind} lookup failed for ${dedupeKey}:`, err);
      return done(false, "lookup_failed");
    }

    if (!target) {
      // Precondition no longer holds — a real "don't send", so keep the claim.
      return done(false, "precondition_failed");
    }

    const allowed = allowlist();
    if (allowed && !allowed.has(target.to.toLowerCase())) {
      return done(false, "not_allowlisted");
    }

    try {
      await deliver(target.to, target.email);
    } catch (err) {
      release(kind, dedupeKey);
      // Never log the message body or the recipient's other account state.
      console.error(`[notifications] ${kind} delivery failed:`, err);
      return done(false, "delivery_failed");
    }

    return done(true, dryRun() ? "dry_run" : "sent");
  } catch (err) {
    // Belt and braces: this function is called from fire-and-forget paths and
    // must not be able to reject.
    console.error(`[notifications] ${kind} failed unexpectedly:`, err);
    return done(false, "error");
  }
}

// ── 1. Welcome ────────────────────────────────────────────────────────────

/**
 * Sent once, right after an account is created. Idempotent on the user row
 * itself: an account is created exactly once, and the age guard below means a
 * stray second call an hour later does nothing even after a restart clears the
 * in-process claim.
 */
const WELCOME_MAX_AGE_MS = 60 * 60 * 1000;

export async function sendWelcome(userId: string): Promise<SendResult> {
  return send("welcome", userId, async () => {
    const user = await db.user.findUnique({
      where: { id: userId },
      select: { email: true, name: true, createdAt: true },
    });
    if (!user?.email) return null;
    if (Date.now() - user.createdAt.getTime() > WELCOME_MAX_AGE_MS) return null;
    return { to: user.email, email: welcomeEmail({ name: user.name }) };
  });
}

// ── 2. Low credits ────────────────────────────────────────────────────────

/**
 * The balance warning. `crossingLedgerId` is the ledger row that took this
 * user below the line — it is the dedupe key, so one crossing produces one
 * email no matter how many times this is called. See scanLowCredits().
 */
export async function sendLowCredits(userId: string, crossingLedgerId: string): Promise<SendResult> {
  return send("low_credits", crossingLedgerId, async () => {
    const user = await db.user.findUnique({ where: { id: userId }, select: { email: true } });
    if (!user?.email) return null;

    // Re-read the balance at send time: they may have topped up between the
    // scan and now, and "you're running low" to someone who just paid is the
    // worst possible version of this email.
    const [balance, avg] = await Promise.all([getBalance(userId), averageBuildCredits(userId)]);
    const state = creditState(balance, avg);
    if (!state.needsWarning) return null;

    return {
      to: user.email,
      email: lowCreditsEmail({
        balance: state.balance,
        avgBuildCredits: state.avgBuildCredits,
        canTopUp: billingEnabled(),
        state,
      }),
    };
  });
}

// ── 3. Build failed ───────────────────────────────────────────────────────

export async function sendBuildFailed(buildId: string): Promise<SendResult> {
  return send("build_failed", buildId, async () => {
    const build = await db.build.findUnique({
      where: { id: buildId },
      select: {
        status: true,
        error: true,
        creditsCharged: true,
        project: { select: { id: true, name: true, user: { select: { email: true } } } },
      },
    });
    if (!build || build.status !== "FAILED") return null;
    if (!build.project.user.email) return null;

    // The email states plainly that they were not charged. Only say it if the
    // ledger agrees: creditsCharged is 0 on the build AND no ledger row points
    // at it. app/api/generate/route.ts never charges a failed build, so this
    // should always hold — but this is a factual claim about someone's money,
    // and it gets verified rather than assumed.
    if (build.creditsCharged !== 0) return null;
    const charged = await db.creditLedger.count({ where: { buildId } });
    if (charged > 0) return null;

    return {
      to: build.project.user.email,
      email: buildFailedEmail({ projectName: build.project.name, projectId: build.project.id }),
    };
  });
}

// ── 4. Site published ─────────────────────────────────────────────────────

const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";

export async function sendSitePublished(projectId: string): Promise<SendResult> {
  return send("site_published", projectId, async () => {
    const project = await db.project.findUnique({
      where: { id: projectId },
      select: {
        id: true,
        name: true,
        slug: true,
        publishedAt: true,
        user: { select: { email: true } },
      },
    });
    if (!project?.publishedAt || !project.user.email) return null;

    return {
      to: project.user.email,
      email: sitePublishedEmail({
        projectName: project.name,
        projectId: project.id,
        // Matches the URL app/api/projects/[id]/publish/route.ts returns on
        // prod. Staging publishes to a path-based URL derived from the request
        // host, which a background job can't know — which is why the cron for
        // this one is meant to run on prod only (see the route).
        siteUrl: `https://${project.slug}.${SITES_BASE}`,
      }),
    };
  });
}

// ── Fire-and-forget wrappers ──────────────────────────────────────────────
//
// These are the ones to call from request paths. They return void, never a
// promise, so there is no await to forget and no rejection to handle: a
// notification physically cannot delay or fail the request that triggered it.
//
// Nothing calls them yet — the routes that would (signup, generate, publish)
// are owned by other modules and this module may not edit them. Each is a
// single line at the call site:
//
//   app/api/auth/signup/route.ts        notifyWelcome(user.id)
//   app/api/auth/google/callback        notifyWelcome(user.id)   [new users only]
//   app/api/generate/route.ts           notifyBuildFailed(build.id)
//   app/api/projects/[id]/publish       notifySitePublished(id)
//
// Wiring notifyWelcome means the cron no longer should: set
// KODELY_NOTIFY_WELCOME_CRON=0 in the same change. The other two are safe to
// wire with the cron still running — the same claim key is used on both paths
// within a process, and the cron's own scan only looks at closed slots.

function fireAndForget(work: Promise<SendResult>): void {
  void work.catch((err) => console.error("[notifications] unreachable:", err));
}

export function notifyWelcome(userId: string): void {
  fireAndForget(sendWelcome(userId));
}

export function notifyLowCredits(userId: string, crossingLedgerId: string): void {
  fireAndForget(sendLowCredits(userId, crossingLedgerId));
}

export function notifyBuildFailed(buildId: string): void {
  fireAndForget(sendBuildFailed(buildId));
}

export function notifySitePublished(projectId: string): void {
  fireAndForget(sendSitePublished(projectId));
}

import { db } from "@/lib/db";
import { averageBuildCredits } from "@/lib/credits";
import { EVENTS } from "@/lib/events";
import { creditState } from "./credit-state";

// ── How this stays idempotent without a schema change ─────────────────────
//
// There is no `sent_emails` table and none can be added here, so nothing can
// record "we told this person". Instead every notification is derived from a
// STATE TRANSITION that lands at one instant, and each run only considers
// transitions inside ONE CLOSED TIME SLOT:
//
//   slot = [floor(now, 15m) - 15m, floor(now, 15m))
//
// The slot is computed from the wall clock, not from when the job happened to
// start, so a run at 12:00:03 and a retry at 12:07 both process exactly
// [11:45, 12:00) and produce exactly the same candidate list. That list is
// then de-duplicated in-process by occurrence id (see claim() in send.ts), so
// overlapping or retried runs within a process send nothing twice.
//
// The transition is the important half, because it is what makes this correct
// rather than merely rate-limited:
//
//   low credits — the ledger row that CROSSED the threshold. "Balance is low"
//                 stays true forever and would re-fire every run; "this row
//                 took them from fine to low" is true of exactly one row, and
//                 that row falls in exactly one slot. A top-up creates a newer
//                 row and disarms it.
//   welcome     — the User row's createdAt. Happens once, by definition.
//   build failed— a Build's endedAt. One row per failure.
//   published   — Project.publishedAt, restricted to the FIRST publish, which
//                 is derived from the count of project.published events.
//
// Known, accepted limits (the alternative to each is duplicate mail, which is
// worse — see the schema note in the report):
//
//   * A run that is skipped entirely loses that slot's notifications. Chosen
//     deliberately: at-most-once, not at-least-once.
//   * A process restart between two runs covering the same slot could resend.
//     The clock-aligned slot makes that a narrow window rather than a loop.
//   * Users who were ALREADY below the threshold when this shipped are never
//     warned — they have no future crossing to detect. That is a feature on
//     day one: it is what stops this from blasting the whole back catalogue.

export const SLOT_MS = 15 * 60 * 1000;

export type Slot = { start: Date; end: Date };

/** The most recent slot that is fully in the past. */
export function previousSlot(now: number = Date.now()): Slot {
  const end = Math.floor(now / SLOT_MS) * SLOT_MS;
  return { start: new Date(end - SLOT_MS), end: new Date(end) };
}

// ── Welcome ───────────────────────────────────────────────────────────────

export async function scanWelcome(slot: Slot): Promise<{ userId: string }[]> {
  const users = await db.user.findMany({
    where: { createdAt: { gte: slot.start, lt: slot.end } },
    select: { id: true },
  });
  return users.map((u) => ({ userId: u.id }));
}

// ── Low credits ───────────────────────────────────────────────────────────

export type LowCreditsDue = {
  userId: string;
  /** The ledger row that crossed the threshold; also the dedupe key. */
  crossingLedgerId: string;
  balanceAfter: number;
  avgBuildCredits: number;
  buildsLeft: number;
};

export async function scanLowCredits(slot: Slot): Promise<LowCreditsDue[]> {
  // Every spend in the slot. Grants are irrelevant — a balance can only cross
  // downwards on a negative delta.
  const rows = await db.creditLedger.findMany({
    where: { createdAt: { gte: slot.start, lt: slot.end }, delta: { lt: 0 } },
    orderBy: { createdAt: "asc" },
    select: { id: true, userId: true, delta: true, balanceAfter: true, createdAt: true },
  });

  // Only the last spend of the slot per user can be the crossing row.
  const lastPerUser = new Map<string, (typeof rows)[number]>();
  for (const row of rows) lastPerUser.set(row.userId, row);

  const due: LowCreditsDue[] = [];

  for (const row of lastPerUser.values()) {
    // Anything newer than this row — another build, a top-up, a reward grant —
    // means this row is no longer the user's current state. Skipping is safe
    // and lossless: the newer row belongs to a later slot and gets its own
    // evaluation on a later run.
    const newer = await db.creditLedger.count({
      where: { userId: row.userId, createdAt: { gt: row.createdAt } },
    });
    if (newer > 0) continue;

    const avg = await averageBuildCredits(row.userId);
    const after = creditState(row.balanceAfter, avg);
    // delta is negative, so this is the balance immediately before the spend.
    const before = creditState(row.balanceAfter - row.delta, avg);

    // The transition, not the condition. Someone who was already low before
    // this build has been told once already and is not told again.
    if (!after.needsWarning || before.needsWarning) continue;

    due.push({
      userId: row.userId,
      crossingLedgerId: row.id,
      balanceAfter: row.balanceAfter,
      avgBuildCredits: avg,
      buildsLeft: after.buildsLeft,
    });
  }

  return due;
}

// ── Build failed ──────────────────────────────────────────────────────────

// app/api/generate/route.ts writes exactly this string when the client hangs
// up mid-build. That is the user closing a tab, not a failure they need to
// hear about — mailing "your build failed" to someone who cancelled is noise.
const ABORTED_ERROR = "Client disconnected.";

export type BuildFailedDue = { buildId: string; userId: string };

export async function scanBuildFailed(slot: Slot): Promise<BuildFailedDue[]> {
  const builds = await db.build.findMany({
    where: {
      status: "FAILED",
      endedAt: { gte: slot.start, lt: slot.end },
      creditsCharged: 0,
    },
    orderBy: { endedAt: "asc" },
    select: {
      id: true,
      createdAt: true,
      error: true,
      project: { select: { userId: true } },
    },
  });

  // At most one per user per run, even if three builds failed in a row: a
  // repeated failure is one bad afternoon, not three emails.
  const lastPerUser = new Map<string, (typeof builds)[number]>();
  for (const b of builds) {
    if (b.error === ABORTED_ERROR) continue;
    lastPerUser.set(b.project.userId, b);
  }

  const due: BuildFailedDue[] = [];

  for (const [userId, build] of lastPerUser) {
    // If they started another build afterwards, they were at the keyboard and
    // already dealt with it. This email is for the person who hit a failure
    // and left.
    const later = await db.build.count({
      where: { project: { userId }, createdAt: { gt: build.createdAt } },
    });
    if (later > 0) continue;

    due.push({ buildId: build.id, userId });
  }

  return due;
}

// ── Site published ────────────────────────────────────────────────────────

export type SitePublishedDue = { projectId: string; userId: string };

/**
 * FIRST publishes only. Project.publishedAt is overwritten on every republish,
 * so the column alone can't tell a first publish from the tenth; the count of
 * `project.published` events for that project can. Events are kept 400 days
 * (EVENT_RETENTION_DAYS), far longer than this ever looks back.
 */
export async function scanSitePublished(slot: Slot): Promise<SitePublishedDue[]> {
  const projects = await db.project.findMany({
    where: { publishedAt: { gte: slot.start, lt: slot.end } },
    select: { id: true, userId: true },
  });

  const due: SitePublishedDue[] = [];

  for (const project of projects) {
    const publishes = await db.event.count({
      where: {
        name: EVENTS.sitePublished,
        props: { path: ["projectId"], equals: project.id },
      },
    });
    // 0 means the event write lost a race (track() is fire-and-forget) — the
    // publishedAt timestamp is authority enough that this is still a publish.
    // 2+ means a republish, which is not worth an email.
    if (publishes > 1) continue;

    due.push({ projectId: project.id, userId: project.userId });
  }

  return due;
}

import { createHash, timingSafeEqual } from "node:crypto";
import {
  previousSlot,
  scanBuildFailed,
  scanLowCredits,
  scanSitePublished,
  scanWelcome,
  SLOT_MS,
  type Slot,
} from "@/lib/notifications/scan";
import {
  sendBuildFailed,
  sendLowCredits,
  sendSitePublished,
  sendWelcome,
  type SendResult,
} from "@/lib/notifications/send";
import type { EmailKind } from "@/lib/notifications/templates";

export const dynamic = "force-dynamic";

// Cron-triggered notification run.
//
// Schedule it every 15 minutes, matching SLOT_MS in lib/notifications/scan.ts:
//
//   */15 * * * * curl -fsS -m 120 -X POST https://kodely.me/api/notifications/run \
//     -H "x-kodely-cron-secret: $KODELY_CRON_SECRET" >/dev/null
//
// Running it MORE often than every 15 minutes is harmless (each run processes
// the same closed slot and the dispatcher de-duplicates). Running it LESS
// often silently drops the slots nobody looked at.
//
// PROD ONLY. Staging shares neither the *.kodely.site wildcard nor prod's
// database, and the published-site URL this job builds is the prod one — see
// the note in sendSitePublished().

/** Never mail more than this in one run, per kind. A notification job that can
 *  address the entire user base needs a ceiling that is visible in the code:
 *  if a bug makes everyone eligible, the blast radius is this number and the
 *  cap shows up in the run's response instead of in everyone's inbox. */
const MAX_PER_KIND = 200;

/** A secret short enough to guess is not a secret; refuse rather than pretend. */
const MIN_SECRET_LENGTH = 16;

// 404, not 401. An unauthenticated caller learns nothing about whether this
// endpoint exists, which is the right answer for a route whose whole job is
// sending mail to other people.
function notFound(): Response {
  return new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });
}

function authorized(req: Request): boolean {
  const expected = process.env.KODELY_CRON_SECRET;
  // Unset means the endpoint is closed, never open.
  if (!expected || expected.length < MIN_SECRET_LENGTH) return false;

  // Header only — never a query parameter. Secrets in URLs end up in nginx
  // access logs, the CDN's logs, and any Referer that leaks out.
  const provided =
    req.headers.get("x-kodely-cron-secret") ??
    req.headers.get("authorization")?.replace(/^Bearer\s+/i, "") ??
    "";
  if (provided === "") return false;

  // Constant time, and over fixed-length digests so the comparison can't leak
  // the secret's length either.
  const a = createHash("sha256").update(provided).digest();
  const b = createHash("sha256").update(expected).digest();
  return timingSafeEqual(a, b);
}

function enabled(name: string, fallback: boolean): boolean {
  const raw = process.env[name];
  if (raw === undefined || raw === "") return fallback;
  return raw === "1" || raw.toLowerCase() === "true";
}

type KindReport = { due: number; sent: number; capped: number; skipped: Record<string, number> };

function emptyReport(): KindReport {
  return { due: 0, sent: 0, capped: 0, skipped: {} };
}

function record(report: KindReport, result: SendResult): void {
  if (result.sent) report.sent++;
  else report.skipped[result.reason] = (report.skipped[result.reason] ?? 0) + 1;
}

/**
 * Send one kind, sequentially and capped. Sequential on purpose: this is a
 * background job with no user waiting, and a single SMTP connection sending a
 * few hundred messages in a row is far kinder to the mail host (and to its
 * reputation) than a burst of parallel connections.
 */
async function run<T>(
  items: T[],
  sender: (item: T) => Promise<SendResult>,
): Promise<KindReport> {
  const report = emptyReport();
  report.due = items.length;
  const batch = items.slice(0, MAX_PER_KIND);
  report.capped = items.length - batch.length;
  for (const item of batch) record(report, await sender(item));
  return report;
}

async function handle(req: Request): Promise<Response> {
  if (!authorized(req)) return notFound();

  const dry = new URL(req.url).searchParams.get("dry") === "1";
  const slot: Slot = previousSlot();

  // Welcome is the one notification that also has a natural inline trigger
  // (the signup route). If that ever gets wired up, set this to 0 in the same
  // change so it isn't sent from both places.
  const wantWelcome = enabled("KODELY_NOTIFY_WELCOME_CRON", true);
  const wantLowCredits = enabled("KODELY_NOTIFY_LOW_CREDITS_CRON", true);
  const wantBuildFailed = enabled("KODELY_NOTIFY_BUILD_FAILED_CRON", true);
  const wantPublished = enabled("KODELY_NOTIFY_PUBLISHED_CRON", true);

  const [welcome, lowCredits, buildFailed, published] = await Promise.all([
    wantWelcome ? scanWelcome(slot) : [],
    wantLowCredits ? scanLowCredits(slot) : [],
    wantBuildFailed ? scanBuildFailed(slot) : [],
    wantPublished ? scanSitePublished(slot) : [],
  ]);

  const body: {
    slot: { start: string; end: string; minutes: number };
    dry: boolean;
    kinds: Partial<Record<EmailKind, KindReport>>;
  } = {
    slot: { start: slot.start.toISOString(), end: slot.end.toISOString(), minutes: SLOT_MS / 60000 },
    dry,
    kinds: {},
  };

  if (dry) {
    // Read-only rehearsal: what WOULD be sent, without touching SMTP or the
    // dedupe map. Counts only — this response carries no email addresses and
    // no account state, so a leaked cron log leaks nothing about anyone.
    body.kinds = {
      welcome: { ...emptyReport(), due: welcome.length },
      low_credits: { ...emptyReport(), due: lowCredits.length },
      build_failed: { ...emptyReport(), due: buildFailed.length },
      site_published: { ...emptyReport(), due: published.length },
    };
    return Response.json(body, { headers: { "Cache-Control": "no-store" } });
  }

  body.kinds.welcome = await run(welcome, (w) => sendWelcome(w.userId));
  body.kinds.low_credits = await run(lowCredits, (l) =>
    sendLowCredits(l.userId, l.crossingLedgerId),
  );
  body.kinds.build_failed = await run(buildFailed, (b) => sendBuildFailed(b.buildId));
  body.kinds.site_published = await run(published, (p) => sendSitePublished(p.projectId));

  const total = Object.values(body.kinds).reduce((sum, k) => sum + (k?.sent ?? 0), 0);
  console.log(
    `[notifications] slot ${body.slot.start} → ${body.slot.end}: sent ${total}`,
    body.kinds,
  );

  return Response.json(body, { headers: { "Cache-Control": "no-store" } });
}

export async function POST(req: Request): Promise<Response> {
  return handle(req);
}

// GET is supported because plenty of cron/uptime runners only do GETs. It is
// not a safe/idempotent GET in the HTTP sense, but it is idempotent in the way
// that matters here: two GETs in the same slot send one set of emails.
export async function GET(req: Request): Promise<Response> {
  return handle(req);
}

