// Map "@/..." aliases to the compiled tree, and bare packages to the repo's node_modules.
const orig = Module._resolveFilename;
Module._resolveFilename = function (request, parent, ...rest) {
  if (request.startsWith("@/") && !request.startsWith("@/../")) {
    const local = path.join(OUT, request.slice(2));
    if (fs.existsSync(local + ".js")) request = local;
  }
  try {
    return orig.call(this, request, parent, ...rest);
  } catch (err) {
    if (!request.startsWith(".") && !path.isAbsolute(request)) {
      return orig.call(this, path.join(REPO, "node_modules", request), parent, ...rest);
    }
    throw err;
  }
};

